INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('64.1', 'Privilegiar a reutilização da água proveniente da limpeza de qualquer tipo de maquinaria, que contenha cascalho, areia, cimento ou inertes similares, após tratamento. Os inertes que resultem do processo de tratamento devem ser recolhidos e encaminhadas para destino final adequado.', 'EE', 9, 101),
('64.2', 'As águas que contenham, ou potencialmente possam conter substâncias químicas, assim como as águas com elevada concentração de óleos e gorduras, devem ser conduzidas para um depósito estanque, sobre terreno impermeabilizado, devendo posteriormente ser encaminhadas para destino final adequado.', 'EE', 9, 102),
('64.3', 'Os efluentes domésticos (serviços sanitários, cozinhas e refeitórios) devem ser devidamente encaminhados para uma fossa séptica estanque ou, em alternativa, tratados antes de serem descarregados no meio recetor. Ao proceder-se à limpeza da fossa, os efluentes e lamas devem ser encaminhados para destino final adequado. Caso seja viável, os efluentes deverão ser encaminhados para um sistema de gestão de águas residuais.', 'EE', 9, 103),
('64.4', 'A recolha dos efluentes provenientes de instalações sanitárias do tipo “móvel” deve garantir a frequência necessária à manutenção das boas condições de higiene, devendo ser realizada por uma empresa licenciada para o efeito.', 'EE', 9, 104),
('65', 'Os resíduos suscetíveis de gerar efluentes contaminados pela ação da percolação das águas pluviais devem ser armazenados em parque coberto.', 'EE', 9, 105),
('66', 'Assegurar a existência de um mapa de registo de quantidades de todas as tipologias de efluentes produzidos em obra, bem como dos consumos de água (humano e industrial).', 'EE', 9, 106),
('67', 'De modo a evitar acidentes, no armazenamento temporário de resíduos perigosos (classificação LER), preservar uma distância mínima de 15 m às margens de linhas de água permanentes ou temporárias.', 'EE', 9, 107),
('68', 'Toda a maquinaria deve ser devidamente inspecionada por forma a garantir o seu correto funcionamento, diminuindo risco de fugas e derrames acidentais e consequente contaminação dos solos e recursos hídricos.', 'EE', 9, 108),
('69', 'Não é permitida a rejeição de qualquer tipo de resíduos, ainda que provisória, nas margens, leitos de linhas de água e zonas de máxima infiltração.', 'EE', 9, 109),
('70', 'O atravessamento de máquinas em leito de cheia deve, preferencialmente, ser efetuado através de estruturas já existentes para o efeito, de forma a afetar o mínimo possível a vegetação ripícola e o próprio leito de cheia. Caso se preveja intercetar linhas de água, para estabelecimento de acessos à obra, têm as mesmas de ser estabelecidas por passagem hidráulica, ainda que a afetação ocorra por um curto período.', 'EE', 9, 110),
('71', 'Na eventual afetação de linhas de água e da vegetação ripícola associada, para além da recuperação da topografia original do leito e das margens deve ser garantida a reposição dos maciços arbustivos, assim como do número de exemplares arbóreos abatidos.', 'EE', 9, 111),
('72', 'Garantir a desobstrução e limpeza de todos os elementos hidráulicos de drenagem que possam ter sido afetados pelas atividades relacionadas com a empreitada. Na sequência da desmatação, da circulação de veículos pesados ou de qualquer outra intervenção na fase de construção deve ser assegurado que as linhas de água, valas e valetas não se encontram assoreados com material proveniente da obra ou resultante das obras (solos, resíduos, material de construção, etc.), que não existem empoçamentos importantes, que não existem riscos de deslizamentos ou ravinamentos importantes junto a linhas de água.', 'EE', 9, 112),
('73', 'No decurso dos trabalhos deverá ser dada especial atenção aos poços e furos existentes na área envolvente, devendo ser evitado qualquer tipo de interferência, nomeadamente aquelas que ponham em causa a integridade do recurso água. Todas as captações de água subterrânea existentes na proximidade dos locais de intervenção devem ser sinalizadas, e vedadas se existir a possibilidade de virem a ser afetadas pela obra e, no caso de poços não cobertos, deve ainda ser avaliada a necessidade da sua cobertura', 'EE', 9, 113),
('74', 'Assegurar a prospeção arqueológica sistemática dos locais de implantação das infraestruturas do projeto, que coincidam com zonas de visibilidade deficiente ou não prospetadas anteriormente, após a desmatação e antes das operações de decapagem e escavação, com a finalidade de colmatar as lacunas de conhecimento.', 'EE | RAP', 10, 114),
('75', 'Avisar a equipa de acompanhamento arqueológico sobre a previsão das ações relacionadas com a remoção e revolvimento do solo (desflorestação/desmatação e decapagem superficiais em ações de preparação e regularização do terreno) e escavações no solo e subsolo com uma antecedência mínima de 8 dias.', 'DO | EE', 10, 115),
('76', 'Assegurar o acompanhamento arqueológico integral, permanente e presencial, de todas as operações que impliquem movimentações dos solos em meio terrestre e subaquático, nos trabalhos iniciados e nas fases preparatórias, como a instalação do estaleiro, abertura/alargamento de acessos ou desmatação. O acompanhamento deve ser continuado e efetivo pelo que se houver mais que uma frente de obra em simultâneo terá de se garantir o acompanhamento de todas as frentes.', 'EE | RAP', 10, 116),
('77', 'As ações de limpeza ou desassoreamento devem ser acompanhadas, nos mesmos termos, por um arqueólogo em cada uma das dragas e um no local de deposição dos sedimentos. A equipa deve estar em permanente contacto, ter garantidas condições de segurança e capacidade de visualização dos trabalhos durante o trabalho, nomeadamente em horário noturno, a fim de, minimizar o risco de perda de bens e destruição de estruturas náuticas ou navais.', 'EE | RAP', 10, 117),
('78', 'As dragas utilizadas devem dispor de um dispositivo de visualização tridimensional de deteção de obstáculos {Obstacles Avoidance Sonar/ OAS} e uma grelha na cabeça da draga com uma malha até 20 cm que permita detetar eventuais vestígios arqueológicos submersos não identificados nos trabalhos arqueológicos. Estas devem ainda ser autopropulsionadas e terem capacidade de posicionamento estável pelos seus próprios meios. A draga ou outra embarcação que lhe esteja afeta deve dispor de equipamento adequado ao controlo em contínuo do seu trabalho.', 'EE | RAP', 10, 118),
('79', 'Realizar trabalhos de prospeção arqueológica com recurso a detetores de metais nas áreas de deposição de dragados em meio terrestre.', 'EE | RAP', 10, 119),
('80', 'Caso venham a ser encontrados vestígios arqueológicos na frente de obra, os trabalhos serão de imediato suspensos nessa frente de obra, ficando o arqueólogo obrigado a comunicar de imediato a situação a tutela, propondo as soluções que considerar mais convenientes com o objetivo de minimizar os impactes. Deve ser tido em considera<ao que as áreas com vestígios arqueológicos conservados e que venham a ser afetados de forma irreversível tem de ser integralmente escavados.', 'EE | RAP', 10, 120);